export function getExperienceBySlug(slug) {
  return experiences.find((e) => e.slug === slug) || null;
}

export function getRelatedExperiences(currentSlug, count = 3) {
  return experiences.filter((e) => e.slug !== currentSlug).slice(0, count);
}